// Replicación entre zonas de disponibilidad de cada servicio de datos. Dos servicios no replican: corrígelos.
// replicacionEntreAz: "ninguna", "por-defecto" (el servicio ya replica) o "activada" (hay que habilitar Multi-AZ).
export const diseno = {
  servicios: [
    { nombre: "base-de-datos-rds", replicacionEntreAz: "ninguna" },
    { nombre: "cache-elasticache", replicacionEntreAz: "ninguna" },
    { nombre: "bucket-s3", replicacionEntreAz: "por-defecto" },
    { nombre: "tabla-dynamodb", replicacionEntreAz: "por-defecto" },
  ],
};

